37	enum MainThreadItem {
38	    Runnable(RunnableVariant),
39	    Delayed {
40	        runnable: RunnableVariant,
41	        millis: i32,
42	    },
43	    Idle {
44	        runnable: RunnableVariant,
45	        timeout: Option<Duration>,
46	    },
