315	        if !self.on_main_thread() {
316	            return None;
317	        }
318	        IDLE_DEADLINE.with(|deadline| {
319	            deadline
320	                .borrow()
321	                .as_ref()
322	                .map(|deadline| Duration::from_secs_f64(deadline.time_remaining() / 1000.0))
