335	fn execute_on_main_thread(window: &web_sys::Window, item: MainThreadItem) {
336	    match item {
337	        MainThreadItem::Runnable(runnable) => {
338	            runnable.run();
339	        }
340	        MainThreadItem::Idle { runnable, timeout } => {
341	            schedule_idle_runnable(window, runnable, timeout);
342	        }
343	        MainThreadItem::Delayed { runnable, millis } => {
344	            let callback = Closure::once_into_js(move || {
345	                runnable.run();
346	            });
347	            window
348	                .set_timeout_with_callback_and_timeout_and_arguments_0(
349	                    callback.unchecked_ref(),
350	                    millis,
351	                )
352	                .ok();
353	        }
354	        MainThreadItem::Function(function) | MainThreadItem::RealtimeFunction(function) => {
355	            function();
356	        }
357	    }
358	}
