360	thread_local! {
361	    /// The deadline of the idle callback currently running; read by
362	    /// [`PlatformDispatcher::idle_time_remaining`] from inside the runnable.
363	    static IDLE_DEADLINE: RefCell<Option<web_sys::IdleDeadline>> = const { RefCell::new(None) };
364	    /// Whether `requestIdleCallback` exists (it is absent on Safari), probed
365	    /// on first use.
366	    static IDLE_CALLBACK_SUPPORTED: Cell<Option<bool>> = const { Cell::new(None) };
367	}
368	
369	/// Registers one `requestIdleCallback` per runnable, mirroring how
370	/// `dispatch_after` maps each timer to its own platform alarm. The browser
371	/// already provides the queue semantics a central pump would rebuild: idle
372	/// callbacks run in registration order, an idle period drains as many as its
373	/// deadline allows, and a callback whose `timeout` expires is posted as an
374	/// ordinary task instead.
375	fn schedule_idle_runnable(
376	    window: &web_sys::Window,
377	    runnable: RunnableVariant,
378	    timeout: Option<Duration>,
379	) {
380	    if !idle_callback_supported(window) {
381	        // Safari: run idle work as ordinary macrotasks. With no metered
382	        // deadline, `idle_time_remaining` stays `None` and idle tasks bound
383	        // their own slices.
384	        schedule_runnable(window, runnable, Priority::Low);
385	        return;
386	    }
387	    let callback = Closure::once_into_js(move |deadline: web_sys::IdleDeadline| {
388	        IDLE_DEADLINE.with(|current| *current.borrow_mut() = Some(deadline));
389	        runnable.run();
390	        IDLE_DEADLINE.with(|current| *current.borrow_mut() = None);
391	    });
392	    let result = match timeout {
393	        Some(timeout) => {
394	            let options = web_sys::IdleRequestOptions::new();
395	            options.set_timeout(timeout.as_millis().min(u32::MAX as u128) as u32);
396	            window.request_idle_callback_with_options(callback.unchecked_ref(), &options)
397	        }
398	        None => window.request_idle_callback(callback.unchecked_ref()),
399	    };
400	    if let Err(error) = result {
401	        log::error!("requestIdleCallback failed: {error:?}");
402	    }
403	}
404	
405	fn idle_callback_supported(window: &web_sys::Window) -> bool {
406	    IDLE_CALLBACK_SUPPORTED.with(|supported| {
407	        if let Some(supported) = supported.get() {
408	            return supported;
409	        }
410	        let probed =
411	            js_sys::Reflect::has(window.as_ref(), &JsValue::from_str("requestIdleCallback"))
412	                .unwrap_or(false);
413	        supported.set(Some(probed));
414	        probed
415	    })
416	}
417	
418	fn schedule_runnable(window: &web_sys::Window, runnable: RunnableVariant, priority: Priority) {
419	    let callback = Closure::once_into_js(move || {
420	        runnable.run();
421	    });
422	    let callback: &js_sys::Function = callback.unchecked_ref();
423	
424	    match priority {
425	        Priority::RealtimeAudio => {
426	            window.queue_microtask(callback);
427	        }
428	        _ => {
429	            // TODO-Wasm: this ought to enqueue so we can dequeue with proper priority
430	            window
431	                .set_timeout_with_callback_and_timeout_and_arguments_0(callback, 0)
432	                .ok();
433	        }
434	    }
435	}
