81	impl std::fmt::Display for WebWindowError {
82	    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
83	        match self {
84	            Self::AlreadyOpen => formatter.write_str(
85	                "GPUI web supports only one top-level window; a window is already open",
86	            ),
87	            Self::ReopeningUnsupported => formatter.write_str(
88	                "reopening the GPUI web top-level window after it closes is not supported",
89	            ),
90	            Self::UnsupportedWindowKind(kind) => write!(
91	                formatter,
92	                "GPUI web does not support {kind} as a separate top-level window; render it inside the normal window instead"
93	            ),
94	            Self::GraphicsInitializationPending => formatter.write_str(
95	                "browser graphics initialization has not completed yet; open windows from the callback passed to Platform::run",
96	            ),
97	            Self::GraphicsUnavailable => formatter.write_str(
98	                "browser graphics are unavailable because graphics initialization or an earlier window creation failed",
99	            ),
100	        }
101	    }
102	}
